
SET search_path TO lyfter_car_rental;

-- SCHEMA:
CREATE TABLE users (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name VARCHAR(50) NOT NULL,
    email VARCHAR(50) UNIQUE NOT NULL,
    username VARCHAR(30) UNIQUE NOT NULL,
    password VARCHAR(30) NOT NULL,
    date_of_birth DATE NOT NULL,
    status VARCHAR(30) NOT NULL CHECK (status IN ('active', 'deactivated', 'payment pending'))
);

CREATE TABLE cars (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    brand VARCHAR(15) NOT NULL,
    model VARCHAR(15) NOT NULL,
    year SMALLINT NOT NULL,
    status VARCHAR(30) NOT NULL CHECK (status IN ('available', 'rental ongoing', 'rent ineligible'))
);

CREATE TABLE rentals (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    car_id INTEGER REFERENCES cars(id),
    user_id INTEGER REFERENCES users(id),
    rental_date DATE DEFAULT CURRENT_DATE,
    status VARCHAR(30) NOT NULL CHECK (status IN ('ongoing', 'returned'))
);

